def transform3(g):
 h,w=len(g),len(g[0]); out=[r[:] for r in g]
 rows=[r for r in range(h) if g[r][0]==1 and g[r][-1]==1]
 cols=[c for c in range(w) if g[0][c]==1 and g[-1][c]==1]
 seen=set()
 for r in range(h):
  for c in range(w):
   if g[r][c]!=2 or (r,c) in seen: continue
   q=[(r,c)];seen.add((r,c)); comp=[]
   for y,x in q:
    comp.append((y,x))
    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
     a,b=y+dy,x+dx
     if 0<=a<h and 0<=b<w and g[a][b]==2 and (a,b) not in seen:seen.add((a,b));q.append((a,b))
   if any(y in rows or x in cols for y,x in comp):
    for y,x in comp:out[y][x]=1
 for y in rows:
  for x in range(w):out[y][x]=1
 for x in cols:
  for y in range(h):out[y][x]=1
 return out
